-- PT111-S1-Q18. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT111-S1-Q18$batch04$ AND q.stimulus=$batch04$The current pattern of human consumption of resources, in which we rely on nonrenewable resources, for example metal ore, must eventually change. Since there is only so much metal ore available, ultimately we must either do without or turn to renewable resources to take its place.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption required by the argument?$batch04$ AND q.correct_choice=$batch04$B$batch04$) THEN RAISE EXCEPTION 'Question changed: PT111-S1-Q18'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT111-S1-Q18$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S1-Q18'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT111-S1-Q18$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Our current reliance on nonrenewable resources must eventually change.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$There is only so much metal ore, so eventually we must either do without it or replace it with renewable resources.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The argument lists two options once metal ore runs out: do without, or switch to renewables. It skips a third: switch to *another nonrenewable* resource. If we could keep doing that forever, the pattern would never have to change.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: we cannot keep replacing one nonrenewable resource with another forever.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT111-S1-Q18$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The argument allows doing without as an option. It does not need a renewable replacement for every resource.$batch04$), ($batch04$B$batch04$, $batch04$Negate it: we *can* replace exhausted nonrenewables with other nonrenewables forever. Then the current pattern never has to change, and the conclusion falls apart.$batch04$), ($batch04$C$batch04$, $batch04$The argument does not need renewables to be impossible to exhaust.$batch04$), ($batch04$D$batch04$, $batch04$Rising or falling consumption only changes when the ore runs out, not whether it does.$batch04$), ($batch04$E$batch04$, $batch04$Doing without is one of the author's own options. The author does not assume it is impossible.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT111-S1-Q18$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
